import {createTreeOrnamentMeshes} from './tree-ornaments.js';
import {decorationCatalog,decorationColors,decorationIcon,validDecorationColor} from './decorations.js';
import * as T from './vendor/three.module.js';
export function createSharedTree(scene,vfx){
 const root=new T.Group();root.name='community-tree-decorations';root.position.set(108,0,35);scene.add(root);
 const ornaments=createTreeOrnamentMeshes(root),{meshes,frames}=ornaments,dummy=new T.Object3D(),tint=new T.Color();let draft={},records=[],signature='',kind='star',color='#e5bb6b',busy=false,lastAdded='',opened=false,selected='',focused='',focusUntil=0;let initialized=false;const flying=new Set();let visibleRecords=[];
 const glow=new T.Mesh(new T.TorusGeometry(.74,.025,8,48),new T.MeshBasicMaterial({color:'#ffe5ac',transparent:true,opacity:0,depthWrite:false,toneMapped:false}));glow.visible=false;root.add(glow);
 const tray=document.createElement('div');tray.id='tree-tools';tray.hidden=true;tray.setAttribute('role','group');tray.setAttribute('aria-label','트리 꾸미기');
 tray.innerHTML='<div class="tree-tools-head"><strong>트리 꾸미기</strong><button data-close aria-label="트리 꾸미기 닫기"><svg viewBox="0 0 24 24"><path d="m7 7 10 10M17 7 7 17"/></svg></button></div><div class="tree-palette tree-kinds"></div><div class="tree-colors"><div class="tree-swatches"></div><label class="tree-custom-color">색상<input type="color" aria-label="장식 사용자 지정 색상"></label></div><div class="tree-footer"><button data-add>장식 달기</button><button data-new hidden>새 장식</button><button data-wish>소원</button><button data-list>소원 목록</button><button data-undo aria-label="마지막 장식 취소" disabled><svg viewBox="0 0 24 24"><path d="M4 5v6h6M4.5 10a8 8 0 1 1 .5 7"/></svg></button></div><p role="status">트리를 눌러 달기</p>';
 for(const [id,item]of Object.entries(decorationCatalog)){const b=document.createElement('button');b.dataset.kind=id;b.setAttribute('aria-label',item.name+' 장식');b.innerHTML=decorationIcon(id);tray.querySelector('.tree-kinds').append(b);}
 for(const value of decorationColors){const b=document.createElement('button');b.dataset.color=value;b.style.setProperty('--swatch',value);b.setAttribute('aria-label','장식 색상 '+value);tray.querySelector('.tree-swatches').append(b);}
 document.body.append(tray);const status=tray.querySelector('p'),picker=tray.querySelector('input[type=color]');
 function controls(){tray.querySelectorAll('[data-kind]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.kind===kind));tray.querySelectorAll('[data-color]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.color.toLowerCase()===color.toLowerCase()));picker.value=color;tray.querySelector('[data-new]').hidden=!selected;tray.querySelector('[data-add]').hidden=!!selected;}
 function locationOf(item){const t=(item.height-2.3)/(32*.82),r=32*.29*(1-t*.94)+.25;return{x:Math.cos(item.angle)*r,y:item.height,z:Math.sin(item.angle)*r};}
 function focus(id,travel=false){const item=records.find(r=>r.id===id);if(!item)return;focused=id;focusUntil=performance.now()+5000;if(travel){const p=locationOf(item);window.dispatchEvent(new CustomEvent('lab:ornament-focus',{detail:{x:108+p.x,y:p.y,z:35+p.z,angle:item.angle}}));}}
 const room=()=>window.sharedRoom?.()||new URL(location.href).searchParams.get('room')||'winter-plaza';
 function render(items){const known=new Set(records.map(item=>item.id));records=items;if(initialized&&vfx){for(const item of items){if(known.has(item.id)||Date.now()-item.createdAt>12000)continue;const p=locationOf(item),own=item.mine&&window.labPlayerState,from=Number.isFinite(item.originX)&&Number.isFinite(item.originY)&&Number.isFinite(item.originZ)?{x:item.originX,y:item.originY,z:item.originZ}:own?{x:own.x,y:own.y+.4,z:own.z}:{x:108+Math.cos(item.angle)*14,y:1.5,z:35+Math.sin(item.angle)*14};flying.add(item.id);vfx.animateWish({id:item.id,from,to:{x:108+p.x,y:p.y,z:35+p.z},kind:item.kind,color:item.color,geometry:meshes[item.kind]?.geometry,frameGeometry:frames[item.kind]?.geometry,onComplete:()=>{flying.delete(item.id);signature='';render(records);focus(item.id);}});}}initialized=true;const next=JSON.stringify(items);if(next===signature)return;signature=next;const counts=Object.fromEntries(Object.keys(meshes).map(k=>[k,0]));visibleRecords=items.filter(item=>!flying.has(item.id));for(const item of visibleRecords){const m=meshes[item.kind];if(!m||counts[item.kind]>=160)continue;const p=locationOf(item);dummy.position.set(p.x,p.y,p.z);dummy.rotation.set(0,Math.PI/2-item.angle,0);dummy.updateMatrix();const index=counts[item.kind]++;m.setMatrixAt(index,dummy.matrix);frames[item.kind].setMatrixAt(index,dummy.matrix);m.setColorAt(index,tint.set(item.color));}for(const [key,m]of Object.entries(meshes)){m.count=counts[key];m.instanceMatrix.needsUpdate=true;if(m.instanceColor)m.instanceColor.needsUpdate=true;frames[key].count=counts[key];frames[key].instanceMatrix.needsUpdate=true;}}
 async function sync(){if(!window.labSocialJoined||document.hidden)return;try{const r=await fetch('/api/tree?room='+encodeURIComponent(room()),{signal:AbortSignal.timeout(8000)});if(r.ok)render((await r.json()).decorations);}catch{}}
 async function mutate(method,body){const r=await fetch('/api/tree',{method,headers:{'Content-Type':'application/json'},body:JSON.stringify(body),signal:AbortSignal.timeout(8000)}),data=await r.json();if(!r.ok)throw Error(data.error||'연결을 확인해 주세요.');return data;}
 async function add(angle,height){if(!opened||busy||selected)return;busy=true;status.textContent='';try{await window.joinSharedActivity();await sync();const data=await mutate('POST',{...draft,kind,color,angle,height});lastAdded=data.id;window.labSound?.(draft.message?'wish':'tree');draft={};tray.querySelector('[data-undo]').disabled=false;await sync();focus(data.id);status.textContent='트리를 눌러 달기';}catch(e){status.textContent=e.message;}finally{busy=false;}}
 async function setColor(value){if(!validDecorationColor(value))return;color=value;controls();if(!selected||busy)return;busy=true;try{await mutate('PATCH',{id:selected,color});await sync();focus(selected);status.textContent='색상을 바꿨습니다.';window.labSound?.('tree');}catch(e){status.textContent=e.message;}finally{busy=false;}}
 function close(){opened=false;selected='';tray.hidden=true;}
 window.placeTreeDecoration=p=>add(Math.atan2(p.z-35,p.x-108),Math.max(3,Math.min(27,p.y)));window.treeDecorationActive=()=>opened;
 tray.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.kind){kind=b.dataset.kind;selected='';controls();status.textContent='트리를 눌러 달기';}else if(b.dataset.color)setColor(b.dataset.color);else if(b.hasAttribute('data-add')){const p=window.labPlayerState||{x:108,z:53};add(Math.atan2(p.z-35,p.x-108),5+Math.random()*19);}else if(b.hasAttribute('data-new')){selected='';controls();status.textContent='트리를 눌러 달기';}else if(b.hasAttribute('data-undo')&&lastAdded&&!busy){busy=true;try{await mutate('DELETE',{id:lastAdded});lastAdded='';selected='';b.disabled=true;await sync();controls();}catch(e){status.textContent=e.message;}finally{busy=false;}}else if(b.hasAttribute('data-close'))close();else if(b.hasAttribute('data-wish'))window.openWishComposer?.();else if(b.hasAttribute('data-list'))window.openWishList?.();});picker.addEventListener('change',()=>setColor(picker.value));
 window.addEventListener('lab:decoration-choice',e=>{if(meshes[e.detail.decoration])kind=e.detail.decoration;if(validDecorationColor(e.detail.color))color=e.detail.color;controls();});
 window.addEventListener('lab:wish-draft',e=>{const {kind:k,color:c,...data}=e.detail;draft=data;if(meshes[k])kind=k;if(validDecorationColor(c))color=c;selected='';controls();});
 window.addEventListener('lab:tree-open',()=>{opened=true;tray.hidden=false;controls();status.textContent='트리를 눌러 달기 · 내 장식을 누르면 색상 변경';sync();});
 window.addEventListener('lab:highlight-ornament',e=>focus(e.detail,true));window.addEventListener('keydown',e=>{if(e.key==='Escape')close();});window.addEventListener('lab:room',()=>{initialized=false;lastAdded='';tray.querySelector('[data-undo]').disabled=true;render([]);sync();});setInterval(sync,2000);sync();controls();
 return{readAt(ray){const hit=ray.intersectObjects(Object.values(meshes),false)[0];if(!hit)return false;const k=Object.keys(meshes).find(k=>meshes[k]===hit.object),item=visibleRecords.filter(r=>r.kind===k)[hit.instanceId];if(!item)return false;if(opened){if(item.mine){selected=item.id;kind=item.kind;color=item.color;controls();status.textContent='색상을 고르면 이 장식에 적용됩니다.';}else status.textContent='다른 방문자의 장식입니다.';focus(item.id);}else window.openWishList?.(item.id);return true;},update(x,z,time=0,still=false){root.visible=!window.labInterior;ornaments.update(time,still);const item=records.find(r=>r.id===focused),remaining=(focusUntil-performance.now())/5000;glow.visible=!!item&&remaining>0;if(glow.visible){const p=locationOf(item);glow.position.set(p.x,p.y,p.z);glow.rotation.y=Math.PI/2-item.angle;glow.scale.setScalar(still?1:1.1+Math.sin(time*5)*.1);glow.material.opacity=Math.min(1,remaining*3);}if(opened&&(window.labInterior||Math.hypot(x-108,z-35)>38))close();}};
}
